internal object DuaNlDraft7 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_jar_su" to DuaText("Toevlucht voor een slechte buur", "O Allah, ik zoek toevlucht bij U tegen een slechte buur op de plaats waar ik permanent woon, want de buurman op reis gaat verder.", "Ter bescherming tegen een slechte buur.", "De Profeet ﷺ beval hiertoe toevlucht te zoeken."),
        "dua_ishfi_abdak" to DuaText("Voor het herstel van een zieke", "O Allah, genees Uw dienaar zodat hij voor U een vijand kan confronteren of voor U in gebed kan gaan.", "Voor de zieke die hem bezoekt.", "De Profeet ﷺ leerde dit voor de zieken te zeggen."),
        "dua_la_mania" to DuaText("Niemand kan achterhouden wat u geeft", "Niemand heeft het recht om aanbeden te worden behalve Allah, alleen, zonder partner. Aan Hem is de heerschappij en aan Hem is de lof, en Hij heeft macht over alle dingen. O Allah, niemand kan achterhouden wat U geeft en niemand kan geven wat U achterhoudt, en de rijkdommen van de rijken baten U niet.", "Na de salam van het verplichte gebed.", "De Profeet ﷺ zei dit na elk verplicht gebed."),
        "dua_slaughtering" to DuaText("Bij het slachten van een dier", "In de naam van Allah, en Allah is de Grootste.", "Bij het offeren of slachten van een dier.", "De Profeet ﷺ zei Bismillah en Takbir tijdens het offeren."),
        "dua_undressing" to DuaText("Bij het uittrekken van kleding", "In de naam van Allah.", "Bij het uittrekken van kleding (voor ghusl of omkleden).", "Het wordt een scherm tussen de ogen van de djinn en de geslachtsdelen van een persoon."),
        "dua_ilbas_jadidan" to DuaText("Iemand in nieuwe kleren zien", "Draag nieuwe, leef prijzenswaardig en sterf als martelaar.", "Over het zien van een moslimbroeder in nieuwe kleren.", "De Profeet ﷺ maakte deze dua toen hij Umar (RA) in nieuwe kleren zag."),
        "dua_hajj_la_riya" to DuaText("Een hadj zonder pronken", "O Allah, (maak er) een hadj van zonder opschepperij en zonder streven naar roem.", "Voor oprechtheid bij het maken van de intentie voor de hadj.", "De Profeet ﷺ maakte deze dua tijdens de hadj."),
        "dua_q_muslimayni_laka" to DuaText("Dua van Ibrahim en Ismail (AS) – Maak ons onderdanig", "Onze Heer, maak ons ​​beiden onderdanig aan U en maak van onze nakomelingen een volk dat onderdanig is aan U. Toon ons onze rituelen van aanbidding en aanvaard ons berouw. U bent inderdaad de Acceptant van berouw, de Barmhartige.", "Een dua van onderwerping voor zichzelf en zijn nakomelingen.", "De dua die werd gemaakt tijdens het bouwen van de Ka'bah."),
        "dua_q_iftah_baynana" to DuaText("Dua van Shu'aib (AS) - Rechter tussen ons", "Onze Heer, oordeel in waarheid tussen ons en ons volk, en U bent de beste rechter.", "Voor een oordeel tussen waarheid en onwaarheid.", "De du van Shu'ayb (AS) toen zijn volk hem verwierp."),
        "dua_q_la_akuna_zahiran" to DuaText("Dua van Musa (AS) — Nooit een helper van criminelen", "Mijn Heer, vanwege de gunst die U mij hebt verleend, zal ik nooit een helper van de criminelen zijn.", "Dankbaarheid voor de zegeningen van Allah en een belofte om overtreders niet te helpen.", "De belofte van Musa (AS) na zijn berouw."),
        "dua_q_nuh_unsurni" to DuaText("Dua van Nuh (AS) - Help mij, ze ontkennen mij", "Mijn Heer, help mij, want zij hebben mij verloochend.", "Wanneer mensen je ontkennen en de waarheid verwerpen.", "De dua van Noeh (AS), die werd beantwoord."),
        "dua_q_ihkum_bil_haqq" to DuaText("Mijn Heer, oordeel met de waarheid", "Mijn Heer, oordeel met de waarheid. En onze Heer is de Barmhartige, Wiens hulp wordt gezocht tegen wat u beschrijft.", "Ondanks leugens en valse beschuldigingen.", "Een dua geleerd aan de profeet ﷺ."),
        "dua_ghalabatid_dayn" to DuaText("Toevlucht tegen verpletterende schulden en vijanden", "O Allah, ik zoek mijn toevlucht bij U tegen de overweldiging door schulden, tegen de overmeestering door een vijand en tegen het leedvermaak van vijanden.", "Bescherming tegen de last van schulden en overheersing door vijanden.", "De Profeet ﷺ zocht zijn toevlucht tegen deze dingen."),
        "dua_faqr_qillah_dhillah" to DuaText("Toevlucht tegen armoede en vernedering", "O Allah, ik zoek toevlucht bij U tegen armoede, schaarste en vernedering, en tegen het onrecht aandoen van anderen of onrecht aangedaan worden.", "Om veilig te zijn voor ontberingen, gebrek en vernedering.", "Een toevluchtsoord onderwezen door de Profeet ﷺ."),
        "dua_five_things_new_muslim" to DuaText("Vergeef, heb genade, begeleid, genees, zorg voor", "O Allah, vergeef mij, heb medelijden met mij, leid mij, schenk mij welzijn en zorg voor mij.", "De Profeet ﷺ leerde deze dua, samen met het gebed, aan nieuwe moslims.", "De Profeet ﷺ zei: deze woorden verzamelen voor jou deze wereld en het Hiernamaals."),
        "dua_ruku_laka_raka_tu" to DuaText("In Ruku - Voor jou boog ik", "O Allah, voor U heb ik gebogen, in U heb ik geloofd en aan U heb ik mij onderworpen. Mijn gehoor, mijn zicht, mijn geest, mijn botten en mijn pezen zijn vernederd voor U.", "In ruku (vooral in vrijwillige gebeden).", "De Profeet ﷺ reciteerde dit in ruku."),
        "dua_sujood_laka_sajadtu" to DuaText("In Sujood – Voor jou knielde ik neer", "O Allah, voor U heb ik mij neergeworpen, in U heb ik geloofd en aan U heb ik mij onderworpen. Mijn gezicht heeft zich ter aarde geworpen voor Degene die het heeft geschapen, gevormd en zijn gehoor en zicht heeft voortgebracht. Gezegend is Allah, de beste der scheppers.", "In sujood (vooral in vrijwillige gebeden).", "De Profeet ﷺ reciteerde dit in sujood."),
        "dua_ruku_sujood_subhanaka" to DuaText("Glorie zij aan u, onze Heer - vergeef mij", "Glorie zij U, O Allah, onze Heer, en alle lof zij U. O Allah, vergeef mij.", "In ruku en sujood.", "Aisha (RA): de Profeet ﷺ zei dit vaak in ruku en sujood."),
        "dua_q_musa_li_akhi" to DuaText("Dua van Musa (AS) - Vergeef mij en mijn broer", "Mijn Heer, vergeef mij en mijn broer en laat ons toe in Uw genade, want U bent de Meest Barmhartige onder de barmhartigen.", "Vergeving voor jezelf en je broer of dierbaren.", "De dua van Musa (AS) voor Harun (AS)."),
        "dua_q_ufawwidu_amri" to DuaText("Ik vertrouw mijn zaken toe aan Allah", "En ik vertrouw mijn zaak toe aan Allah. Voorwaar, Allah is Alziend over Zijn dienaren.", "Wanneer mensen zich tegen je verzetten en de zaak aan Allah moet worden overgelaten.", "De woorden van de gelovige uit het volk van Farao; Allah beschermde hem toen tegen hun kwade complotten."),
        "dua_q_hawariyyun" to DuaText("Dua van de discipelen – Neem ons op met de getuigen", "Onze Heer, we hebben geloofd in wat U hebt geopenbaard en we hebben de Boodschapper gevolgd, dus noteer ons onder de getuigen.", "Voor standvastigheid in het geloof en in het volgen van de Boodschapper.", "De dua van de discipelen van Isa (AS)."),
        "dua_q_la_tukhzini" to DuaText("Dua van Ibrahim (AS) - Maak mij niet te schande", "En maak mij niet te schande op de Dag waarop zij zullen herrijzen.", "Om veilig te zijn voor schande op de Dag der Opstanding.", "De dua van Ibrahim (AS) voor het Hiernamaals."),
        "dua_iftar_laka_sumtu" to DuaText("Iftar – Voor jou heb ik gevast", "O Allah, voor U heb ik gevast en met Uw voorziening verbreek ik mijn vasten.", "Bij het verbreken van het vasten (de bekende iftar dua).", "De Profeet ﷺ zei dit tijdens iftar. Het is een mursalvertelling, versterkt door andere overleveringen; het reciteren ervan tijdens iftar is de gewoonte van de Hanafi’s en de meerderheid."),
        "dua_iftar_ibn_umar" to DuaText("Iftar - Vergeef mij door uw grote genade", "O Allah, ik vraag U bij Uw genade, die alle dingen omvat, om mij te vergeven.", "Bij iftar maakte Abdullah ibn Amr (RA) deze dua; de dua van een vastende persoon bij iftar wordt niet afgewezen.", "Hadith: de dua van de vastende persoon ten tijde van iftar wordt niet afgewezen."),
        "dua_inni_saim" to DuaText("Wanneer geprovoceerd tijdens het vasten", "Ik ben aan het vasten, ik ben aan het vasten.", "Wanneer iemand u beledigt of ruzie met u maakt tijdens het vasten.", "De Profeet ﷺ zei: vasten is een schild, dus de vastende persoon mag niet obsceen spreken of onwetend handelen – als iemand ruzie maakt, zeg dit dan twee keer."),
        "dua_eid_takbeer" to DuaText("Takbier op weg naar Eid", "Allah is de Grootste, Allah is de Grootste, er is geen god dan Allah, en Allah is de Grootste, Allah is de Grootste, en alle lof is voor Allah.", "Vanaf de nacht van de maanwaarneming tot het Eid al-Fitr-gebed, vooral op weg naar de Eid-grond.", "Het Koranische gebod: 'zodat je de telling voltooit en de grootheid van Allah verkondigt' (al-Baqarah 2:185). Ibn Mas'ud (RA) zei deze takbir."),
        "dua_ahsin_aqibatana" to DuaText("Maak ons einde goed in alle zaken", "O Allah, maak ons ​​einde goed in alle zaken, en bescherm ons tegen schande in deze wereld en bestraffing in het Hiernamaals.", "Voor een goed resultaat in elke zaak.", "Degene die deze dua maakt en sterft voordat hij wordt berecht, sterft (veilig voor berechting)."),
        "dua_fadlika_wa_rahmatik" to DuaText("Ik vraag om uw milddadigheid en genade", "O Allah, ik vraag U om Uw milddadigheid en Uw genade, want niemand bezit deze behalve U.", "Als je om voorziening en genade vraagt.", "Gasten kwamen naar de Profeet ﷺ toen er geen eten was; hij maakte deze dua, en toen kwam er een geschenk."),
        "dua_allahu_akbar_kabira_2696" to DuaText("Woorden geleerd aan een bedoeïen", "Niemand heeft het recht om aanbeden te worden behalve Allah, alleen, zonder partner. Allah is de Grootste, enorm; overvloedige lof is voor Allah; glorie zij Allah, Heer der werelden; en er is geen macht of kracht behalve bij Allah, de Almachtige, de Wijze.", "Een uitgebreide zin van dhikr en dua – onderwezen aan een bedoeïen.", "Hierna leerde hij 'Allahummaghfir li warhamni wahdini warzuqni' zeggen."),
        "dua_ma_qaddamtu_akhkhartu" to DuaText("Vergeef wat ik ervoor en erna heb gestuurd", "O Allah, vergeef mij de zonden die ik ervoor en erna heb begaan, wat ik in het geheim heb gedaan en wat ik openlijk heb gedaan, mijn excessen en wat U beter weet dan ik. Jij bent degene die naar voren brengt en degene die achteruit gaat; er is geen god behalve Jij.", "Na de tashahhud en salawat, vóór de salam.", "De Profeet ﷺ reciteerde dit aan het einde van het gebed, tussen de tashahhud en de salam."),
        "dua_jiddi_wa_hazli" to DuaText("Vergeef mijn ernst en mijn grap", "O Allah, vergeef mij de zonden die ik ernstig en voor de grap, per ongeluk en opzettelijk heb begaan – en dat zit allemaal in mij.", "Vergeving voor elke vorm van zonde, bekend en onbekend.", "Een uitgebreide istighfar van de Profeet ﷺ."),
        "dua_rising_ruku_mil" to DuaText("Na Ruku – Lof vult de hemel", "Onze Heer, aan U behoort alle lof, het vullen van de hemel, het vullen van de aarde en het vervullen van wat U daarna nog meer wilt.", "Na het opstaan ​​uit ruku, samen met 'Rabbana lakal-hamd'.", "De Profeet ﷺ zei dit toen hij opstond uit ruku."),
        "dua_istiftah_kabira" to DuaText("Allah is de Grootste, overvloedig geprezen", "Allah is de Grootste, enorm; overvloedige lof is voor Allah; en glorie zij Allah, 's ochtends en 's avonds.", "Bij het begin van het gebed (een vorm van de openingslofprijzing).", "De Profeet ﷺ zei: de poorten van de hemel werden ervoor geopend."),
        "dua_q_ashku_bathhi" to DuaText("Dua van Yaqub (AS) – Ik klaag alleen bij Allah", "Ik klaag over mijn angst en mijn verdriet alleen bij Allah.", "In diep verdriet en scheiding.", "Ya'qub (AS) zei dit tijdens zijn scheiding van Yusuf (AS)."),
        "dua_q_khayrun_hafiza" to DuaText("Allah is de beste beschermer", "Allah is de beste Beschermer, en Hij is de Meest Barmhartige onder de barmhartigen.", "Wanneer u kinderen of dierbaren op reis stuurt.", "Ya'qub (AS) zei dit terwijl hij zijn zoon aan Allah toevertrouwde."),
        "dua_q_aqraba_rashada" to DuaText("Moge mijn Heer mij dichter naar het goede leiden", "Misschien zal mijn Heer mij leiden naar wat dichter bij het juiste gedrag ligt.", "Bij het zoeken naar een betere manier in bepaalde zaken.", "De Profeet ﷺ kreeg te horen dat hij dit moest zeggen als hij het vergeten was."),
        "dua_q_sawa_as_sabil" to DuaText("Dua van Musa (AS) – Leid mij op de goede weg", "Misschien zal mijn Heer mij op de juiste weg leiden.", "Wanneer u een nieuwe reis of een onbekende weg begint.", "Musa (AS) zei dit terwijl hij zich naar Madyan wendde."),
        "dua_q_not_among_wrongdoers" to DuaText("Plaats mij niet onder de overtreders", "Mijn Heer, plaats mij niet onder de onrechtvaardige mensen.", "Een dua waarin Allah wordt gevraagd iemand apart te houden van de onrechtvaardigen.", "Een dua waarin Allah wordt gevraagd iemand apart te houden van de onrechtvaardigen."),
        "dua_q_do_not_make_us_trial" to DuaText("Maak ons geen beproeving", "Onze Heer, maak ons ​​geen beproeving voor de ongelovigen, en vergeef ons, onze Heer. U bent inderdaad de Almachtige, de Wijze.", "De dua van Ibrahim (AS) en zijn metgezellen.", "De dua van Ibrahim (AS) en zijn metgezellen."),
        "dua_morning_witness" to DuaText("Ochtendgetuige van Tawhid", "O Allah, ik ben de ochtend ingegaan en heb U, de dragers van Uw Troon, Uw engelen en Uw hele schepping opgeroepen om te getuigen dat U Allah bent, dat er geen god is behalve U, alleen, zonder partner, en dat Mohammed ﷺ Uw dienaar en Boodschapper is.", "Het verhaal vermeldt dat je het vier keer in de ochtend moet zeggen.", "Het verhaal vermeldt dat je het vier keer in de ochtend moet zeggen."),
